        sum: Optional['types.ThreadSumAggregateInput'] = None,
        min: Optional['types.ThreadMinAggregateInput'] = None,
        max: Optional['types.ThreadMaxAggregateInput'] = None,
        having: Optional['types.ThreadScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.ThreadCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.ThreadScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.ThreadScalarFieldKeys', 'types.SortOrder']]]] = None,
