        sum: Optional['types.SenderSumAggregateInput'] = None,
        min: Optional['types.SenderMinAggregateInput'] = None,
        max: Optional['types.SenderMaxAggregateInput'] = None,
        having: Optional['types.SenderScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.SenderCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.SenderScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.SenderScalarFieldKeys', 'types.SortOrder']]]] = None,
