        min: Optional['types.DeadlineMinAggregateInput'] = None,
        max: Optional['types.DeadlineMaxAggregateInput'] = None,
        having: Optional['types.DeadlineScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.DeadlineCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.DeadlineScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.DeadlineScalarFieldKeys', 'types.SortOrder']]]] = None,
